const docs = (function(){ try { return $('Leer COMPROBANTES_WA').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const movs = (function(){ try { return $('Leer BANCOS_MOV').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const creds = (function(){ try { return $('Leer CREDITOS').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const hoy = new Date();
const hace7 = new Date(hoy - 7*86400000);

const sinMatch = docs.filter(d => ['SIN_MATCH','AMBIGUO','ERROR','REVISAR'].includes(d.ESTADO));
const pendCont = movs.filter(m => m.ESTADO_CONTABLE === 'PENDIENTE' && m.TIPO !== 'TRASLADO');
const ingSem = movs.filter(m => m.TIPO === 'INGRESO' && new Date(m.FECHA) >= hace7).reduce((s,m) => s + (parseFloat(m.VALOR)||0), 0);
const egrSem = movs.filter(m => m.TIPO === 'EGRESO' && new Date(m.FECHA) >= hace7).reduce((s,m) => s + (parseFloat(m.VALOR)||0), 0);
const credVig = creds.filter(c => c.ESTADO === 'VIGENTE');

const fmt = n => '$' + Math.round(n).toLocaleString('es-CO');
let txt = `📊 *MeUp · Resumen financiero ${hoy.toISOString().slice(0,10)}*\n\n`;
txt += `Ingresos últimos 7 días: ${fmt(ingSem)}\n`;
txt += `Egresos últimos 7 días: ${fmt(egrSem)}\n`;
txt += `Flujo neto: ${fmt(ingSem + egrSem)}\n\n`;
txt += `⚠️ Comprobantes por revisar: ${sinMatch.length}\n`;
sinMatch.slice(0,5).forEach(d => { txt += `  · ${d.ID_DOC} ${d.OCR_CLIENTE || d.NOMBRE_CONTACTO || '?'} ${d.OCR_VALOR ? fmt(parseFloat(d.OCR_VALOR)) : ''} [${d.ESTADO}]\n`; });
txt += `\n📌 Movimientos sin contabilizar en SIIGO: ${pendCont.length}\n`;
txt += `\n🏦 Créditos vigentes: ${credVig.length}\n`;
credVig.forEach(c => { txt += `  · ${c.BANCO} ${c.NUMERO_CREDITO} ${c.MONEDA} ${c.VALOR_COP || c.VALOR_USD}\n`; });
return [{ json: { texto: txt, alertas: sinMatch.length + pendCont.length } }];
